cat > drafts/memo.css <<'EOF'
@page { size: Letter; margin: 0.7in 0.75in; }
html { font-family: "Charter", "Georgia", serif; font-size: 10.5pt; line-height: 1.32; color: #111; }
body { margin: 0; max-width: none; padding: 0; }
header#title-block-header { display: none; }
p { margin: 0 0 0.45em 0; text-align: left; }
h3 { font-family: "Helvetica Neue", Arial, sans-serif; font-size: 10.5pt; margin: 0.75em 0 0.3em 0; }
ul { margin: 0.2em 0 0.4em 0; padding-left: 1.2em; }
li { margin: 0.1em 0; }
.exhibit { page-break-before: always; }
.exhibit h3 { font-size: 11pt; }
table { border-collapse: collapse; width: 100%; font-size: 9.5pt; margin: 0.6em 0; }
th, td { border-bottom: 1px solid #bbb; padding: 4px 6px; }
th { border-bottom: 1.5px solid #333; text-align: left; }
td:not(:first-child), th:not(:first-child) { text-align: right; white-space: nowrap; }
.exhibit p { font-size: 9.5pt; }
EOF
cat > drafts/render_pdf.sh <<'EOF'
#!/bin/bash
# Render a Markdown deliverable to PDF: pandoc -> HTML -> headless Chrome.
# Usage: bash drafts/render_pdf.sh memo.md memo.pdf
set -e
src="$1"; out="$2"; dir="$(cd "$(dirname "$0")" && pwd)"
tmp="$(mktemp -d)"
pandoc "$src" -s --css "$dir/memo.css" --embed-resources --metadata pagetitle=Memo -o "$tmp/doc.html"
python3 - "$tmp/doc.html" "$PWD/$out" <<'PY'
import subprocess, sys
chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
subprocess.run([chrome, "--headless=new", "--disable-gpu", "--no-pdf-header-footer",
                f"--print-to-pdf={sys.argv[2]}", "file://" + sys.argv[1]],
               check=True, timeout=90, capture_output=True)
PY
python3 -c "import re,sys; d=open(sys.argv[1],'rb').read(); print(sys.argv[1], 'pages:', len(re.findall(rb'/Type\s*/Page[^s]', d)))" "$out"
EOF
bash drafts/render_pdf.sh memo.md memo.pdf

